<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Requests\DestinationRequest; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Destination; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\AuditService; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\NotificationDispatcher; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\UrlGuard;
class DestinationController extends Controller { use \LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers\Concerns\BulkDeletes; public function index(){return view('iapm::destinations.index',['destinations'=>Destination::withCount('actions')->paginate(50)]);}
    public function bulkDestroy(Request $r,AuditService $audit){abort_unless($r->user()->can('manage iapm destinations'),403);$ids=$this->bulkIds($r);$deleted=0;$skipped=[];\Illuminate\Support\Facades\DB::transaction(function()use($ids,&$deleted,&$skipped){foreach(Destination::whereIn('id',$ids)->withCount('actions')->get() as $destination){if($destination->actions_count>0){$skipped[]=$destination->name;continue;}$destination->delete();$deleted++;}});$audit->record($r,'bulk_deleted','destination',null,null,['deleted'=>$deleted,'skipped'=>$skipped]);$msg="Deleted {$deleted} destination(s).";if($skipped)$msg.=' Skipped (used by policy actions): '.implode(', ',$skipped).'.';return redirect()->route('iapm.destinations.index')->with($skipped?'error':'status',$msg);} public function create(){return view('iapm::destinations.form',['destination'=>new Destination,'configuration'=>[]]);} public function store(DestinationRequest $r,AuditService $audit,UrlGuard $guard){$data=$r->validated();$guard->assertAllowed($data['url'],$data['allow_private_networks']);$config=$this->config($data);$d=Destination::create(['name'=>$data['name'],'type'=>$data['type'],'enabled'=>$data['enabled'],'configuration_encrypted'=>$config]);$audit->record($r,'created','destination',$d,null,['name'=>$d->name,'type'=>$d->type,'enabled'=>$d->enabled]);return redirect()->route('iapm.destinations.edit',$d)->with('status','Destination created.');} public function edit(Destination $destination){$c=(array)$destination->configuration_encrypted;unset($c['password'],$c['bearer_token']);return view('iapm::destinations.form',['destination'=>$destination,'configuration'=>$c]);} public function update(DestinationRequest $r,Destination $destination,AuditService $audit,UrlGuard $guard){$data=$r->validated();$guard->assertAllowed($data['url'],$data['allow_private_networks']);$before=['name'=>$destination->name,'type'=>$destination->type,'enabled'=>$destination->enabled];$config=array_replace((array)$destination->configuration_encrypted,$this->config($data));if(blank($data['password']??null))$config['password']=$destination->configuration_encrypted['password']??null;if(blank($data['bearer_token']??null))$config['bearer_token']=$destination->configuration_encrypted['bearer_token']??null;$destination->update(['name'=>$data['name'],'type'=>$data['type'],'enabled'=>$data['enabled'],'configuration_encrypted'=>$config]);$audit->record($r,'updated','destination',$destination,$before,['name'=>$destination->name,'type'=>$destination->type,'enabled'=>$destination->enabled]);return back()->with('status','Destination updated.');} public function destroy(Request $r,Destination $destination,AuditService $audit){abort_unless($r->user()->can('manage iapm destinations'),403);if($destination->actions()->exists())return back()->withErrors('Destination is used by policy actions.');$before=['name'=>$destination->name,'type'=>$destination->type];$destination->delete();$audit->record($r,'deleted','destination',$destination->id,$before,null);return redirect()->route('iapm.destinations.index');} public function test(Request $r,Destination $destination,NotificationDispatcher $dispatcher,AuditService $audit){abort_unless($r->user()->can('test iapm destinations'),403);$data=$r->validate(['receiver'=>['required','string','max:128']]);$result=$dispatcher->test($destination,$data['receiver'],'IAPM test message from '.(config('app.url')?:gethostname()).'. Destination configuration is working.');$audit->record($r,'tested','destination',$destination,null,['successful'=>$result->successful,'status'=>$result->status]);return back()->with($result->successful?'status':'error',$result->successful?'Test succeeded.':'Test failed: '.$result->error);} private function config(array $d):array{return ['url'=>$d['url'],'username'=>$d['username']??null,'password'=>$d['password']??null,'bearer_token'=>$d['bearer_token']??null,'default_receiver'=>$d['default_receiver']??null,'mode'=>$d['mode'],'connect_timeout'=>$d['connect_timeout'],'timeout'=>$d['timeout'],'retry_count'=>$d['retry_count'],'retry_delay_ms'=>$d['retry_delay_ms'],'verify_tls'=>$d['verify_tls'],'allow_private_networks'=>$d['allow_private_networks'],'headers'=>json_decode($d['headers_json']??'[]',true,32,JSON_THROW_ON_ERROR)];} }
